create function pg_temp.lp_literacy_mock_unpack(node jsonb, dictionary jsonb) returns jsonb
language plpgsql immutable as $decode$
declare result jsonb; reference integer; slot integer; decoded_key text; begin
  if dictionary is null or jsonb_typeof(dictionary) <> 'array' then raise exception 'Invalid mock catalogue dictionary'; end if;
  if jsonb_typeof(node) = 'number' then
    if (node#>>'{}') !~ '^(0|[1-9][0-9]*)$' then raise exception 'Invalid mock catalogue reference'; end if;
