    if jsonb_typeof(dictionary->reference) in ('array', 'object') then raise exception 'Nonprimitive mock catalogue reference'; end if;
    return dictionary->reference;
  end if;
  if node is null or jsonb_typeof(node) <> 'array' then raise exception 'Invalid encoded mock catalogue node'; end if;
  if node->0 = '0'::jsonb then
