    into result from jsonb_array_elements(node) with ordinality as elements(value, ordinal) where ordinal > 1;
  elsif node->0 = '1'::jsonb and mod(jsonb_array_length(node), 2) = 1 then
    result := '{}'::jsonb;
    for slot in 1..jsonb_array_length(node) - 1 by 2 loop
      if jsonb_typeof(node->slot) <> 'number' or (node->>slot) !~ '^(0|[1-9][0-9]*)$'
        then raise exception 'Invalid mock catalogue key reference'; end if;
      reference := (node->>slot)::integer;
      if reference >= jsonb_array_length(dictionary) or jsonb_typeof(dictionary->reference) <> 'string'
        then raise exception 'Missing or nonstring mock catalogue key'; end if;
